// AI-generated by OpenAI Codex: diagram verification and PDF export, not app tests.
const {chromium}=require('playwright');
const fs=require('fs');
const path=require('path');
function browserOptions(){
 const candidates=process.platform==='darwin'?['/Applications/Google Chrome.app/Contents/MacOS/Google Chrome']:
  process.platform==='win32'?[path.join(process.env.PROGRAMFILES||'C:\\Program Files','Google/Chrome/Application/chrome.exe'),path.join(process.env['PROGRAMFILES(X86)']||'C:\\Program Files (x86)','Google/Chrome/Application/chrome.exe')]:
  ['/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'];
 const executablePath=process.env.CHROME_BIN||candidates.find(candidate=>fs.existsSync(candidate));
 if(process.env.CHROME_BIN&&!fs.existsSync(executablePath))throw new Error('CHROME_BIN does not exist: '+executablePath);
 return {headless:true,...(executablePath?{executablePath}:{})};
}
(async()=>{
 const browser=await chromium.launch(browserOptions());
 const page=await browser.newPage({viewport:{width:1440,height:1060},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('file://'+path.join(__dirname,'source-wireframe-board.html'));
 await page.screenshot({path:path.join(__dirname,'preview-navigation.png')});
 const count=await page.locator('article.state').count();
 if(count!==54)throw new Error('Expected 54 frames, got '+count);
 const badLinks=await page.evaluate(()=>Array.from(document.querySelectorAll('a[href^="#"]')).filter(a=>!document.getElementById(a.getAttribute('href').slice(1))).map(a=>a.getAttribute('href')));
 if(badLinks.length)throw new Error('Broken frame navigation: '+badLinks);
 // Text checks are performed in vector coordinates, before browser image scaling.
 const overflows=await page.evaluate(()=>Array.from(document.querySelectorAll('.phone-button svg text')).flatMap(t=>{
  const b=t.getBBox();return b.x<3||b.x+b.width>257?[{frame:t.closest('article').id,text:t.textContent,x:b.x,width:b.width}]:[];
 }));
 await page.locator('[data-focus="E3"]').click();
 await page.locator('#focus[open]').waitFor();
 if((await page.locator('#focus-title').textContent())!=='Slide review')throw new Error('Inspect view failed');
 await page.screenshot({path:path.join(__dirname,'preview-inspect.png')});
 await page.locator('#focus-content [data-jump="E1"]').first().click();
 if(await page.locator('#focus').evaluate(d=>d.open))throw new Error('Transition did not close details');
 await page.locator('#all-notes').click();
 if((await page.locator('.state-notes[open]').count())!==54)throw new Error('Source toggle failed');
 await page.locator('#all-notes').click();
 for(const width of [1440,1024,736,375]){
  await page.setViewportSize({width,height:1060});
  const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
  if(overflow)throw new Error('Horizontal layout overflow at '+width);
 }
 await page.setViewportSize({width:1440,height:1060});
 await page.emulateMedia({media:'print'});
 await page.pdf({path:path.join(__dirname,'outloud-pr31-wireframe.pdf'),printBackground:true,preferCSSPageSize:true,displayHeaderFooter:true,
  headerTemplate:'<div></div>',footerTemplate:'<div style="font-family:Arial;font-size:8px;width:100%;text-align:center;color:#626262">OutLoud · PR31 f1af9dd · <span class="pageNumber"></span> / <span class="totalPages"></span></div>'});
 const result={wireframes:count,frame_links:'all targets exist',inspection:'open, show source, transition navigation and close passed',notes_toggle:'54 notes opened and closed',responsive_widths:[1440,1024,736,375],horizontal_overflow:false,browser_errors:errors,svg_text_overflows:overflows};
 fs.writeFileSync(path.join(__dirname,'browser-verification.json'),JSON.stringify(result,null,2)+'\n');
 console.log(JSON.stringify(result));
 await browser.close();
 if(errors.length||overflows.length)process.exitCode=1;
})().catch(e=>{console.error(e);process.exit(1)});
